@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="d-inline-flex align-items-center my-2">
    <span class="me-2">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-4 text-decoration-none"
                @onclick="() => Rate(star)"
                title="@star star(s)">
            @(star <= SelectedRating ? "★" : "☆")
        </button>
    }
    <span class="ms-2 text-muted small">
        @if (RatingCount > 0)
        {
            @($"{CurrentRating:F1} avg ({RatingCount} ratings)")
        }
        else
        {
            @("No ratings yet")
        }
    </span>
</div>

@if (Submitted)
{
    <div class="alert alert-success mt-2 py-1 px-2 d-inline-block">
        Thanks for rating!
    </div>
}

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int SelectedRating { get; set; }
    private bool Submitted { get; set; }

    private void Rate(int stars)
    {
        SelectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }

        Submitted = true;
    }
}

