toolArgs.file_text:
@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (SubmittedSuccessfully)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe has been added to the collection.
        <a href="recipe/@NewRecipeId">View it here</a>.
    </div>
}

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="Model.Title" placeholder="e.g. Grandma's Apple Pie" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="Model.Category">
            <option value="">-- Select a category --</option>
            <option value="appetizers">Appetizers</option>
            <option value="main-courses">Main Courses</option>
            <option value="desserts">Desserts</option>
        </InputSelect>
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="Model.IngredientsText"
                       placeholder="1 cup flour&#10;2 eggs&#10;1/2 cup sugar" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="Model.StepsText"
                       placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Bake for 30 minutes." />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel Model { get; set; } = new();
    private bool SubmittedSuccessfully { get; set; }
    private int NewRecipeId { get; set; }

    private void HandleSubmit()
    {
        var categoryName = Model.Category switch
        {
            "appetizers" => "Appetizers",
            "main-courses" => "Main Courses",
            "desserts" => "Desserts",
            _ => "Other"
        };

        var recipe = new Recipe
        {
            Title = Model.Title,
            Category = categoryName,
            CategorySlug = Model.Category,
            Ingredients = Model.IngredientsText.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = Model.StepsText.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        };

        RecipeService.AddRecipe(recipe);
        NewRecipeId = recipe.Id;
        SubmittedSuccessfully = true;
        Model = new();
    }

    private class RecipeFormModel
    {
        public string Title { get; set; } = string.Empty;
        public string Category { get; set; } = string.Empty;
        public string IngredientsText { get; set; } = string.Empty;
        public string StepsText { get; set; } = string.Empty;
    }
}

